insert into public.banners (id, placement, eyebrow, title, text, cta_label, cta_href, image, image_mobile, theme, sort, active) values
  ('9d11ee3b-de41-4e89-9e18-cb9fe79aa53c', 'home-carousel', 'Temporada Otoño · Invierno', 'Capas que se sienten *tan bien* como se ven', 'Gabardinas, satines y tejidos americanos recién llegados. Pocas piezas por modelo.', 'Ver novedades', 'tienda.html?orden=nuevo', 'media/banners/nueva-coleccion.webp', '', 'light', 0, true),
  ('5f120398-e20c-4f86-b1a7-5a9ced9e2aa3', 'home-carousel', 'Rebajas de temporada', 'Hasta *30%* en piezas seleccionadas', 'Vestidos, suéteres y satines con precio especial mientras haya existencias.', 'Ver ofertas', 'tienda.html?oferta=1', 'media/banners/rebajas.webp', '', 'light', 1, true),
  ('e94095ef-2743-4861-8270-2bebc53c3c10', 'home-carousel', 'Denim americano', 'Mezclilla con *etiqueta original*', 'Wide leg, rectos, faldas y chamarras. Cortes clásicos que mejoran con cada uso.', 'Ver mezclilla', 'tienda.html?q=mezclilla', 'media/banners/denim.webp', '', 'light', 2, true)
insert into public.lookbooks (id, eyebrow, title, text, image, hotspots, sort, active) values
  ('e8b4d713-7eca-41f9-8897-f07f08f7dc0c', 'Arma tu look', 'Sastrería *suave*', 'Blazer marfil, top acanalado y pantalón de pinzas arena: la fórmula para verte impecable de la oficina a la cena.', 'images/lookbook/look-01.webp', '[{"product":"top-acanalado","color":"Negro","x":54.2,"y":31},{"product":"pantalon-sastre-pinzas","color":"Arena","x":73.3,"y":60.5},{"product":"blazer-sastre","color":"Marfil","x":26.7,"y":44},{"product":"bolsa-estructurada","color":"Negro","x":25,"y":84}]'::jsonb, 0, true)
insert into public.faq (id, question, answer, sort, active) values
  ('bb21ee39-fa90-4b63-bf88-7225eac42b06', '¿Cómo hago mi pedido?', 'Agrega tus prendas a la bolsa, elige talla y color, y presiona «Enviar pedido por WhatsApp». Se abrirá un mensaje con tu pedido listo; solo envíalo y te respondemos para confirmar existencias, pago y envío.', 0, true),
  ('ba21eca6-f990-49d0-be88-7092ebc42c99', '¿La ropa es original?', 'Sí. Todas nuestras prendas son importadas de Estados Unidos y llegan con su etiqueta original. Seleccionamos cada pieza revisando calidad, tela y acabados.', 1, true),
  ('b921eb13-fc90-4e89-bd88-6effe8c427e0', '¿Cómo sé cuál es mi talla?', 'Las prendas usan tallas americanas. Consulta la guía de tallas en cada producto y, si tienes duda, pídenos por WhatsApp las medidas exactas de la prenda que te gusta.', 2, true),
  ('b821e980-fb90-4cf6-bc88-6d6ce9c42973', '¿Qué formas de pago aceptan?', 'Transferencia, depósito y efectivo al entregar en zonas seleccionadas. Al confirmar tu pedido por WhatsApp te compartimos los datos de pago.', 3, true),
  ('bf21f485-fe90-41af-bb88-6bd9eec43152', '¿Hacen envíos?', 'Sí, enviamos a todo México por paquetería. El costo y el tiempo de entrega dependen de tu ciudad; te los confirmamos por WhatsApp antes de que pagues.', 4, true),
  ('be21f2f2-fd90-401c-ba88-6a46efc432e5', '¿Puedo cambiar una prenda?', 'Escríbenos por WhatsApp en cuanto recibas tu pedido. Si la prenda está sin usar y conserva su etiqueta, te ayudamos con el cambio de talla según disponibilidad.', 5, true)
insert into public.site_content (key, value) values
  ('hero', '{"eyebrow":"Otoño · Invierno 2026","title":"Moda americana, *elegida para ti.*","subtitle":"Prendas con etiqueta original, seleccionadas para mujer, niñas, niños y hombre.","video":"media/video/divani-hero.mp4","videoPortrait":"media/video/divani-hero-portrait.mp4","poster":"media/video/divani-hero-poster.webp","posterPortrait":"media/video/divani-hero-portrait-poster.webp"}'::jsonb),
  ('ribbons', '{"primary":["Nueva temporada","*Divani*","Ropa americana","*Fashion in you*","Etiqueta original","*Divani*","Piezas limitadas"],"secondary":["Compra por WhatsApp","*Mujer*","Envíos a todo México","*Niñas & niños*","Atención personal","*Hombre*"]}'::jsonb),
  ('editorial', '{"image":"media/editorial/silk-02.webp","eyebrow":"Divani · Fashion in you","title":"Ropa americana. *Etiqueta original.*"}'::jsonb),
  ('kids', '{"title":"Para los *más pequeños*","lead":"Vestidos de fiesta, mezclilla y básicos suaves en tallas americanas de 2T a 12.","girlsImage":"images/categories/ninas.webp","boysImage":"images/categories/ninos.webp"}'::jsonb),
  ('about', '{"title":"Moda americana *premium*, elegida pieza por pieza.","image":"media/editorial/silk-03.webp","paragraphs":["Divani nació de una idea sencilla: que vestir bien no dependa de cruzar la frontera. Traemos desde Estados Unidos prendas con su etiqueta original y las seleccionamos con cuidado, pensando en cómo te van a quedar y en cuánto las vas a usar.","Buscamos cortes que favorecen, telas que se sienten bien y detalles que hacen la diferencia: un satín con buena caída, una mezclilla que dura, un blazer que estructura. Cada modelo llega en pocas piezas, así que lo que encuentras aquí no lo vas a ver en todos lados.","Y como la ropa se elige mejor platicando, te atendemos por WhatsApp: te damos medidas, te ayudamos con la talla y te acompañamos hasta que tu pedido llegue a tus manos."]}'::jsonb),
  ('men', '{"title":"Básicos *para él*","bannerTitle":"Camisas, polos, chinos y mezclilla índigo","image":"images/categories/hombre.webp"}'::jsonb),
  ('vip', '{"title":"Entérate *primero*","text":"Únete a nuestra lista de difusión y recibe por WhatsApp los nuevos ingresos en cuanto llegan.","image":"media/editorial/silk-01.webp"}'::jsonb)
